def aligned_tree(net, pos, root="any", kappa=L1.KAPPA):
    """沿 BFS 生成树做**平行移动积分**，得到全局坐标（确定性、`O(E)`、无迭代）。

    规则（纯 id + 环序）：BFS 从 root 出发；处理边 i→w 时
      g = M_i · dir_i(w)                              （i 的全局标架下的 i→w 方向）
      p_w = p_i + (r_i + r_w)·g                       （树边精确满足相切目标长）
      M_w = R(u→−g)，其中 u = dir_w(i)                （把 w 标架的「指向 i」转到 −g）

    返回 {"pos", "frames", "tree_edges", "holonomy"}：
      holonomy[(i,w)] = 用 i 的标架预测 w 的位置与树位置之差（非树边）。
      该量**非零是几何事实**（离散曲率无法在平面容纳），不是误差 —— 见模块 docstring。
    """
    ids = net.ids()
    if not ids:
        return {"pos": {}, "frames": [], "tree_edges": [], "holonomy": {}}
    if root == "any":
        root = random.choice(ids)
    tree = bfs_tree(net, root)
    tree_edges = sorted((tree[v], v) for v in ids if v in tree)
    pos = {v: list(pos[v]) for v in ids}
    frames = [deepcopy(pos)]
    for (i, w) in tree_edges:
        g = rot_from_dir(dir_of(net, pos, w, i))
        pos[w] = [p + (RADIUS[i] + RADIUS[w]) * g[d] for d, p in enumerate(pos[i])]
        pos[w][2] = 0.0
        rot = rot_from_dir(dir_of(net, pos, i, w))
        for d in range(3):
            pos[w][d] -= rot[d] * pos[w][2]
        frames.append(deepcopy(pos))
    holonomy = {}
    for (i, w) in tree_edges:
        pred = [p + (RADIUS[i] + RADIUS[w]) * g[d]
                for d, p in enumerate(pos[i])]
        holonomy[(i, w)] = [pred[d] - pos[w][d] for d in range(3)]
    return {"pos": pos, "frames": frames, "tree_edges": tree_edges,
            "holonomy": holonomy}

def sigma_global(net):
    """GT-008 全局 σ = |V| / |E| = 2 / ⟨deg⟩。"""
    return 2.0 / net.avg_degree() if net.V() else 0.0

def _union_nets(nets):
    """把若干旋转系统并成一个**不连通**的旋转系统（各分量 id 依次平移，互不干涉）。

    用于构造多分量种子（如 icosa ⊔ tetra = 12 壳 + 四面体两个独立分量）。
    这是「独立 12 壳作为分量」的唯一可达构造入口 —— 单连通种子下分量数不可增
    （L0-A11），故独立壳只可能是初始条件，不能自发涌现。
    """
    ids = [set()]  # 列表，每个元素是该分量的 id 集合（不排序）
    for net in nets:
        ids.append(set(net["rot"]))

    pos = {}
    for comp in range(1, len(ids)):
        for v in ids[comp]:
            pos[v] = (len(ids) + v) % (len(ids) + len(pos))

    rot = []
    for comp in range(1, len(ids)):
        rot.append([pos[v] for v in ids[comp]])

    return {"rot": rot, "sigma": None, "deg": None, "nframes": 0}

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    es = {(net.rot[e][0], net.rot[e][1]) for e in net.rot}
    return {(u, v) if u < v else (v, u) for u, v in es}

def snap(net):
    """帧快照（深拷贝旋转系统，保留 id 计数器）——L3 以 id 对齐，故必须冻结每帧。"""
    pos = {v: list(p) for v, p in net.pos.items()}
    rot = {v: list(r) for v in net.rot}
    return RotNet(rot, pos=pos, ids=net.ids, dead=net.dead)

def _edge_set(rows):
    """无向边集合（规范化 (min,max)，确定性排序）。"""
    s = {(r["v"], r["w"]) for r in rows}
    return sorted((min(v, w), max(v, w)) for v, w in s)

def _to_rotnet(rows, cols, n):
    """重建后的 CSR → RotNet（宿主侧物化，CPU 内核的既有接口）。

    这里是唯一不可免的 O(V) 宿主开销：把列式 CSR 摊回 dict[int, list[int]]，
    供 l0_core 的只读查询 / 审计使用（帧调度本身不依赖它）。
    """
    g = {}
    for u in range(n):
        g[u] = [int(cols[r]) for r in range(rows[u], rows[u + 1])]
    return g

def seed_at_V():
    """构造 V ≥ 12 的三角剖分起点：由 icosa 逐次锥化首个真面，每次 +1 元胞。"""
    # --- S1 基础：icosa 粒子位置 ---
    ico = icosahedron()
    pos = {v: ico["pos"][v] for v in ico["nodes"]}
    # --- S2 逐次锥化 ---
    for _ in range(12):
        nxt = {v: pos[v] for v in pos}
        for (a, b, c) in ico["faces"]:
            mid = (tuple((pos[a][i] + pos[b][i]) / 2.0 for i in range(3))
                   if a < b < c else None)
            if mid is None:
                continue
            nxt[f"n{len(nxt)}"] = mid
            nxt[a], nxt[b], nxt[c] = (f"n{len(nxt) - 3}", f"n{len(nxt) - 2}",
                                     f"n{len(nxt) - 1}")
        pos = nxt
    # --- S3 返回 ---
    return {"nodes": sorted(pos), "edges": [], "faces": [], "pos": pos}
